const b = $json.body || $json;
const LEVELS = ['LOW','MEDIUM','HIGH','CRITICAL'];
const KNOWN = ['accident','drunk_driving','wrong_way','red_light','overspeeding','triple_riding','no_helmet','no_seatbelt','illegal_parking'];
const errors = [];
const type = String(b.type || b.violation_type || '').toLowerCase().trim().replace(/[ -]+/g, '_');
const description = String(b.description || b.reason || b.summary || '');
if (!type && !description) errors.push('need a type or a description');
const raw = b.severity;
let lvl = -1;
if (raw !== undefined && raw !== null && raw !== '') {
  if (!isNaN(Number(raw))) lvl = [0,0,0,1,2,3][Math.min(Math.max(Math.round(Number(raw)),0),5)];
  else lvl = LEVELS.indexOf(String(raw).toUpperCase());
  if (lvl < 0) errors.push('severity must be LOW|MEDIUM|HIGH|CRITICAL or a number 1-5');
}
const loc = b.location || {};
const lat = loc.lat !== undefined ? Number(loc.lat) : (b.lat !== undefined ? Number(b.lat) : NaN);
const lng = loc.lng !== undefined ? Number(loc.lng) : (b.lng !== undefined ? Number(b.lng) : NaN);
const place = loc.place || b.place || '';
if (!place && (isNaN(lat) || isNaN(lng))) errors.push('need location.place or location.lat + location.lng');
return [{ json: {
  valid: errors.length === 0, errors,
  violation_id: b.violation_id || ('V-' + Date.now().toString(36).toUpperCase()),
  type: type || 'unclassified', jev_level: lvl,
  known: KNOWN.includes(type) && lvl >= 0,
  ai_used: false,
  confidence: b.confidence === undefined ? 1 : Number(b.confidence),
  plate: String(b.plate || '').toUpperCase().replace(/[^A-Za-z0-9]/g, ''),
  speed: b.speed ?? null, speed_limit: b.speed_limit ?? null,
  place, lat: isNaN(lat) ? null : lat, lng: isNaN(lng) ? null : lng,
  timestamp: b.timestamp || new Date().toISOString(),
  image_url: b.image_url || '',
  jev_reason: description,
  flags: Array.isArray(b.flags) ? b.flags : []
} }];

const LEVELS = ['LOW','MEDIUM','HIGH','CRITICAL'];
const d = $json;
const s = $getWorkflowStaticData('global');
s.plates = s.plates || {};
const now = Date.now();
let lvl = d.jev_level;
const reasons = [(d.ai_used ? 'AI triage (unknown case) rated this ' : 'Jev rated this ') + LEVELS[lvl] + ' (' + Math.round(d.confidence * 100) + '% confident)'];
if (d.ai_used && d.jev_reason) reasons.push('AI reasoning: ' + d.jev_reason);
let prior = 0;
if (d.plate) { const h = (s.plates[d.plate] || []).filter(t => now - t < 86400000); prior = h.length; h.push(now); s.plates[d.plate] = h; }
if (prior >= 2) { lvl++; reasons.push('Repeat offender: ' + prior + ' earlier violations by this plate in 24h (+1 level)'); }
const f = d.flags;
if (f.includes('school_zone') || f.includes('hospital_zone')) { lvl++; reasons.push('Happened in a school/hospital zone (+1 level)'); }
const hr = Number(new Date(d.timestamp).toLocaleString('en-GB', { timeZone: 'Asia/Kolkata', hour: '2-digit', hour12: false })) % 24;
if ((hr >= 22 || hr < 5) && ['drunk_driving','overspeeding','wrong_way'].includes(d.type)) { lvl++; reasons.push('Night-time high-risk violation (+1 level)'); }
let review = !!d.ai_failed;
if (d.confidence < 0.5) { lvl--; review = true; reasons.push('Low detection confidence: dropped 1 level and flagged for human review'); }
if (d.ai_failed) reasons.push('AI was unavailable: kept at HIGH and flagged for human review');
if (d.type === 'accident' || f.includes('injury')) { lvl = 3; reasons.push('Accident or injury: always CRITICAL'); }
lvl = Math.max(0, Math.min(3, lvl));
return [{ json: { ...d, final_level: lvl, final_severity: LEVELS[lvl], reasons, needs_review: review, prior_violations: prior } }];

// ALL routing decisions live here. Change this node, nothing else.
const config = {
  demo_inbox: 'DEMO_INBOX_PLACEHOLDER@example.com', // demo mode: every role is a +alias of this inbox
  zones: [
    { id: 'NORTH',   name: 'North Bengaluru',      station: 'Yelahanka Traffic PS',    lat: 13.100, lng: 77.596 },
    { id: 'NW',      name: 'North-West Bengaluru', station: 'Yeshwanthpur Traffic PS', lat: 13.028, lng: 77.540 },
    { id: 'CENTRAL', name: 'Central Bengaluru',    station: 'Cubbon Park Traffic PS',  lat: 12.977, lng: 77.592 },
    { id: 'EAST',    name: 'East Bengaluru',       station: 'Indiranagar Traffic PS',  lat: 12.978, lng: 77.640 },
    { id: 'WHITE',   name: 'Whitefield',           station: 'Whitefield Traffic PS',   lat: 12.970, lng: 77.750 },
    { id: 'SOUTH',   name: 'South Bengaluru',      station: 'Jayanagar Traffic PS',    lat: 12.925, lng: 77.583 },
    { id: 'SE',      name: 'South-East Bengaluru', station: 'Madiwala Traffic PS',     lat: 12.922, lng: 77.620 },
    { id: 'ECITY',   name: 'Electronic City',      station: 'Electronic City Traffic PS', lat: 12.845, lng: 77.660 }
  ],
  default_zone: { id: 'CONTROL', name: 'Unassigned', station: 'City Traffic Control Room', keywords: [] },
  roles: {
    inspector: 'Zone Traffic Inspector',
    sho: 'Station House Officer',
    dcp: 'DCP Traffic (Zone)',
    control: 'City Traffic Control Room',
    ambulance: 'Ambulance Dispatch (108)'
  },
  // who gets emailed at each final severity
  escalation: {
    LOW: [],
    MEDIUM: ['inspector'],
    HIGH: ['inspector', 'sho'],
    CRITICAL: ['inspector', 'sho', 'dcp', 'control']
  },
  sla: { LOW: 'No action - logged only', MEDIUM: 'Issue e-challan within 24 hours', HIGH: 'Respond within 30 minutes', CRITICAL: 'Respond within 5 minutes' },
  colors: { LOW: '#6b7280', MEDIUM: '#d97706', HIGH: '#ea580c', CRITICAL: '#dc2626' }
};
return $input.all().map(i => ({ json: { ...i.json, config } }));

const d = $json; const c = d.config; const sev = d.final_severity;
const rad = x => x * Math.PI / 180;
const km = (a, b, p, q) => { const h = Math.sin(rad(p - a) / 2) ** 2 + Math.cos(rad(a)) * Math.cos(rad(p)) * Math.sin(rad(q - b) / 2) ** 2; return 12742 * Math.asin(Math.sqrt(h)); };
let zone = null, how = '';
if (d.lat !== null && d.lng !== null) {
  const best = c.zones.map(z => ({ z, k: km(d.lat, d.lng, z.lat, z.lng) })).sort((a, b) => a.k - b.k)[0];
  zone = best.z; how = 'nearest zone centre (' + best.k.toFixed(1) + ' km away)';
}
if (!zone) { zone = c.default_zone; how = 'no coordinates: sent to control room'; }
const [u, dom] = c.demo_inbox.split('@');
const addr = r => u + '+' + r + '-' + zone.id.toLowerCase() + '@' + dom;
const roles = c.escalation[sev];
const to = roles.map(addr);
const notified = roles.map(r => c.roles[r] + ' - ' + zone.station);
const ambulance = sev === 'CRITICAL' && (d.type === 'accident' || d.flags.includes('injury'));
const pretty = d.type.split('_').map(w => w[0].toUpperCase() + w.slice(1)).join(' ');
const ist = new Date(d.timestamp).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });
const place = d.place || (d.lat + ', ' + d.lng);
const map = d.lat !== null ? 'https://www.google.com/maps?q=' + d.lat + ',' + d.lng : '';
const col = c.colors[sev];
const rows = [['Violation', pretty], ['Plate', d.plate || 'not readable'], ['Location', place], ['Zone / Station', zone.name + ' - ' + zone.station], ['Time (IST)', ist]];
if (d.speed) rows.push(['Speed', d.speed + ' km/h' + (d.speed_limit ? ' (limit ' + d.speed_limit + ')' : '')]);
rows.push(['Case ID', d.violation_id]);
const tr = rows.map(r => '<tr><td style=\'padding:6px 12px;color:#6b7280\'>' + r[0] + '</td><td style=\'padding:6px 12px;font-weight:600\'>' + r[1] + '</td></tr>').join('');
const why = d.reasons.map(x => '<li>' + x + '</li>').join('') + '<li>Routed to ' + zone.name + ' by ' + how + '</li>';
const demo = '<p style=\'font-size:11px;color:#9ca3af\'>DEMO MODE: in production this goes to: ' + notified.join('; ') + '</p>';
const html = '<div style=\'font-family:Arial,sans-serif;max-width:560px;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden\'>'
  + '<div style=\'background:' + col + ';color:#fff;padding:14px 18px;font-size:18px;font-weight:700\'>' + sev + ' - ' + pretty + '</div>'
  + '<div style=\'padding:14px 18px\'><p style=\'margin:0 0 8px\'><b>Action needed:</b> ' + c.sla[sev] + '</p>'
  + (d.needs_review ? '<p style=\'color:#b45309\'><b>Low confidence: please verify the evidence before acting.</b></p>' : '')
  + (d.jev_reason ? '<p style=\'font-style:italic\'>Jev: ' + d.jev_reason + '</p>' : '')
  + '<table style=\'border-collapse:collapse;font-size:14px\'>' + tr + '</table>'
  + (map ? '<p><a href=\'' + map + '\'>Open location on map</a></p>' : '')
  + (d.image_url ? '<p><img src=\'' + d.image_url + '\' style=\'max-width:100%;border-radius:6px\'></p>' : '')
  + '<p style=\'margin-bottom:4px\'><b>Why it was routed this way</b></p><ul style=\'margin-top:0;font-size:13px\'>' + why + '</ul>' + demo + '</div></div>';
const subject = '[' + sev + '] ' + pretty + ' - ' + (d.plate || 'unknown plate') + ' - ' + (d.place || zone.name);
const amb_html = '<div style=\'font-family:Arial,sans-serif\'><h2 style=\'color:#dc2626\'>Medical response requested</h2><p>Accident with possible injury at <b>' + place + '</b> (' + zone.name + ').</p>' + (map ? '<p><a href=\'' + map + '\'>Open location on map</a></p>' : '') + '<p>Case ' + d.violation_id + ' - ' + ist + '</p>' + demo + '</div>';
const s = $getWorkflowStaticData('global'); s.log = s.log || [];
s.log.push({ id: d.violation_id, at: d.timestamp, type: d.type, severity: sev, zone: zone.id, plate: d.plate, notified: roles });
if (s.log.length > 200) s.log.shift();
return [{ json: { ...d, zone, to, subject, html, ambulance, ambulance_to: addr('ambulance'), ambulance_subject: '[MEDICAL] Accident at ' + place, ambulance_html: amb_html,
  response: { status: sev === 'LOW' ? 'logged' : 'dispatched', violation_id: d.violation_id, severity: sev, zone: zone.name, station: zone.station, notified, ambulance_alerted: ambulance, sla: c.sla[sev], reasons: d.reasons } } }];

