const d = $('Known case?').item.json;
const LEVELS = ['LOW','MEDIUM','HIGH','CRITICAL'];
let ai = null;
if ($json.severity) ai = $json;
else { try { const t = String($json.text || '').replace(/```json|```/g, '').trim(); ai = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); } catch (e) {} }
if (!ai || LEVELS.indexOf(String(ai.severity).toUpperCase()) < 0) {
  return [{ json: { ...d, ai_used: true, ai_failed: true, jev_level: Math.max(d.jev_level, 2), confidence: 0.5, jev_reason: 'AI unavailable, defaulted to HIGH for safety. ' + d.jev_reason } }];
}
const aiLvl = LEVELS.indexOf(String(ai.severity).toUpperCase());
const type = String(ai.type || d.type).toLowerCase().trim().replace(/[ -]+/g, '_') || 'unclassified';
const flags = [...new Set([...d.flags, ...(Array.isArray(ai.flags) ? ai.flags : [])])];
return [{ json: { ...d, ai_used: true, type, flags, jev_level: Math.max(d.jev_level, aiLvl), confidence: Math.min(1, Math.max(0, Number(ai.confidence) || 0.6)), jev_reason: String(ai.reasoning || '') } }];

const bin = $input.first().binary;
const raw = $json.body || {};
// The Connect app names its fields differently (violation, latitude, longitude, plate_number): accept both.
const body = { ...raw, lat: raw.lat ?? raw.latitude, lng: raw.lng ?? raw.longitude, plate: raw.plate ?? raw.plate_number, type: raw.type ?? raw.violation };
let url = '';
if (bin && Object.keys(bin).length) { const k = Object.keys(bin)[0]; const buf = await this.helpers.getBinaryDataBuffer(0, k); url = 'data:' + (bin[k].mimeType || 'image/jpeg') + ';base64,' + buf.toString('base64'); }
else if (body.image_base64) url = String(body.image_base64).startsWith('data:') ? body.image_base64 : 'data:image/jpeg;base64,' + body.image_base64;
else if (body.image_url) url = body.image_url;
const prompt = 'You are a traffic enforcement camera analyst in India. Look at the image and report what traffic violations or dangerous events are visible, for example accident, red light jumping, wrong-way driving, no helmet, triple riding, no seatbelt, overspeeding, illegal parking, signs of drunk driving. Reply with ONLY a JSON object with keys: violation_visible (true or false), description (two sentences: what is happening, which vehicles, whether anyone looks hurt), plate (number plate text if readable, else empty string), flags (array that may contain injury, school_zone, hospital_zone, only if clearly visible), confidence (number 0 to 1 for how sure you are about what you see).';
const vision_body = { model: 'google/gemini-2.5-flash-lite', temperature: 0.1, response_format: { type: 'json_object' }, messages: [{ role: 'user', content: [{ type: 'text', text: prompt }, { type: 'image_url', image_url: { url } }] }] };
return [{ json: { body, has_image: !!url, vision_body: url ? vision_body : null } }];

let vis = null;
try { const c = $json.choices[0].message.content; const t = String(c).replace(/```json|```/g, '').trim(); vis = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); } catch (e) {}
const failed = !vis;
vis = vis || { violation_visible: true, description: '', plate: '', flags: [], confidence: 0.5 };
const state = 'Traffic camera analysis. ' + (failed ? 'Image could not be analysed.' : (vis.violation_visible ? '' : 'No violation visible. ') + vis.description);
const jev_body = { model: 'jev-latest', state, questions: {
  type: { type: 'choice', instructions: 'Which traffic violation or event does this camera analysis describe?', criteria: { accident: 'a collision or crash, someone may be hurt', drunk_driving: 'signs of drunk driving such as weaving', wrong_way: 'vehicle going against traffic', red_light: 'vehicle crossing a red signal', overspeeding: 'vehicle going over the speed limit', triple_riding: 'three or more people on one two-wheeler', no_helmet: 'two-wheeler rider without a helmet', no_seatbelt: 'car occupant without a seatbelt', illegal_parking: 'vehicle parked where not allowed', none: 'no traffic violation is visible', other: 'a violation or hazard not in this list' } },
  severity: { type: 'choice', instructions: 'How dangerous is this to people on the road?', criteria: { LOW: 'minor, no real danger', MEDIUM: 'rule broken, low danger', HIGH: 'clear danger to others', CRITICAL: 'life at risk or injury' } } } };
return [{ json: { vis, failed, jev_body } }];

const { vis, failed } = $('Parse Vision').item.json;
const m = $('Prepare Image').item.json.body || {};
const LEVELS = ['LOW','MEDIUM','HIGH','CRITICAL'];
const KNOWN = ['accident','drunk_driving','wrong_way','red_light','overspeeding','triple_riding','no_helmet','no_seatbelt','illegal_parking'];
const jev = ($json.answers && $json.answers.type && $json.answers.severity) ? $json.answers : null;
let type = 'unclassified', lvl = -1, tconf = 0.5, sconf = 0.5;
if (jev) { type = jev.type.choice; tconf = jev.type.confidence; lvl = LEVELS.indexOf(jev.severity.choice); sconf = jev.severity.confidence; if (type === 'other') type = 'unclassified'; }
const no_violation = !failed && (vis.violation_visible === false || type === 'none');
let known = KNOWN.includes(type) && tconf >= 0.6 && lvl >= 0;
if (failed) { known = true; lvl = Math.max(lvl, 2); }
const errors = [];
const lat = m.lat !== undefined ? Number(m.lat) : NaN; const lng = m.lng !== undefined ? Number(m.lng) : NaN;
const place = m.place || '';
if (!place && (isNaN(lat) || isNaN(lng))) errors.push('need place or lat + lng with the image');
const note = jev ? ' [Jev: ' + type + ' ' + Math.round(tconf * 100) + '%, severity ' + LEVELS[lvl] + ' ' + Math.round(sconf * 100) + '%]' : ' [Jev unavailable]';
const flags = [...new Set([...(Array.isArray(vis.flags) ? vis.flags : []), ...(Array.isArray(m.flags) ? m.flags : [])])];
return [{ json: {
  source: 'image', no_violation, valid: errors.length === 0, errors,
  violation_id: m.violation_id || ('V-' + Date.now().toString(36).toUpperCase()),
  type, jev_level: lvl, known, ai_used: false, ai_failed: failed,
  confidence: Math.min(Number(vis.confidence) || 0.5, jev ? tconf : 1),
  plate: String(vis.plate || m.plate || '').toUpperCase().replace(/[^A-Za-z0-9]/g, ''),
  speed: m.speed ?? null, speed_limit: m.speed_limit ?? null,
  place, lat: isNaN(lat) ? null : lat, lng: isNaN(lng) ? null : lng,
  timestamp: m.timestamp || new Date().toISOString(),
  image_url: m.image_url || '',
  jev_reason: (failed ? 'Image analysis failed, needs human review. ' : '') + (vis.description || '') + note,
  flags
} }];
